      "path": "pnpm-workspace.yaml",
      "content": "packages:\n  - 'shared'\n  - 'packages/*'\n\n# SDK peers 不自动安装，运行时由 DSH profile 树解析\n# （原 true 只为聚合包发布时解析 peers，现已不需要）。\nautoInstallPeers: false\n\n# 根包作为可安装 bundle（dsh.bundle）依赖聚合包；仓库内开发时把该 range\n# 链接到 workspace 工程（版本同源），profile 里的 git 安装仍走 npm registry。\nlinkWorkspacePackages: true\n\nallowBuilds:\n  # The cloudflared postinstall downloads the platform binary (the auto-tunnel\n  # feature ships its own tunnel client — users install nothing).\n  cloudflared: true\n  cpu-features: true\n  esbuild: true\n  node-pty: true\n  ssh2: true\n\n# Upstream packaging defect (reported at 0.1.5-alpha.2, re-verified against the\n# 0.2.1-rc.3 tarballs on 2026-10-24): published SDK packages import\n# runtime dependencies their published manifests never declare, so vitest/node\n# resolution fails for workspace consumers. Restore them at the versions the\n# source pins; the host web bundle supplies its own copies at runtime. Reported\n# as upstream packaging defects; no installed file is patched.\n#\n# @deepseek-ai/dsh-sandbox is a different case: dsh-tools@0.1.6-alpha.1 declares\n# it as a required peer AND imports it at module top level (it did neither at\n# 0.1.5-rc.1), so the root devDependencies carry it as a host face instead of a\n# packageExtensions patch.\npackageExtensions:\n  '@deepseek-ai/dsh-client-store@0.2.1-rc.3':\n    dependencies:\n      zustand: '~4.4.7'\n      immer: '^10.1.1'\n  '@deepseek-ai/dsh-client-ui-primitives@0.2.1-rc.3':\n    dependencies:\n      anser: '^2.3.5'\n      clsx: '^2.0.0'\n      # New at 0.1.6-alpha.1: the emitted lib/index.js imports `diff` for its\n      # DiffBlock renderer, and the published manifest still declares no\n      # runtime dependencies at all. Version read from the official host\n      # install (`@deepseek-ai/dsh@0.1.6-alpha.1` -> diff 9.0.0).\n      diff: '^9.0.0'\n      katex: '^0.16.47'\n      shiki: '^4.3.1'\n      '@shikijs/langs': '^4.3.1'\n      mdast-util-from-markdown: '^2.0.3'\n      mdast-util-gfm: '^3.1.0'\n      mdast-util-math: '^3.0.0'\n      micromark-core-commonmark: '^2.0.3'\n      micromark-extension-gfm: '^3.0.0'\n      micromark-extension-math: '^3.1.0'\n      micromark-factory-space: '^2.0.1'\n      micromark-util-character: '^2.1.1'\n      micromark-util-classify-character: '^2.0.1'\n      micromark-util-sanitize-uri: '^2.0.1'\n      micromark-util-symbol: '^2.0.1'\n      # New at 0.1.7-alpha.1: the emitted lib/index.js imports\n      # `@deepseek-ai/dsh-util-workspace-path` for its workspace-relative path\n      # rendering, and the published manifest still declares no dependencies at\n      # all (peer `@deepseek-ai/cordis` only). Version read from the cohort's own\n      # publish; it is an exact pin in the official source devDependencies.\n      '@deepseek-ai/dsh-util-workspace-path': '0.2.1-rc.3'\n      # The emitted lib/index.js also imports `@deepseek-ai/dsh-util-code-language`,\n      # which the published manifest likewise omits. The package's cohort pin is\n      # the exact target version.\n      '@deepseek-ai/dsh-util-code-language': '0.2.1-rc.3'\n      # New at 0.1.6-alpha.2: the emitted lib/index.js imports `simple-icons`\n      # for the markdown link glyphs, and the published manifest still declares\n      # no runtime dependencies at all. Version is the exact pin the official\n      # source resolves (packages/client/ui-primitives devDependencies ->\n      # simple-icons 16.31.0).\n      simple-icons: '16.31.0'\n\nminimumReleaseAgeExclude:\n  - '@deepseek-ai/dsh-agent-default-model@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-agent@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-api-remotes@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-attachment@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-brand@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-connection@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-locale@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-ui-conversation@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-ui-primitives@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-ui-settings@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-ui-sidebar@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-ui-slots@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-ui-theme@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-commands@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-credentials@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-goal@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-host-directory-picker@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-host-webserver@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-launch-environment@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-llm-retry@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-llm@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-native-command@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-sandbox@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-session-persistence@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-session-projection-cache@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-session-projection@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-session-query@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-session-title@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-session@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-settings@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-skill@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-subagent@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-subprocess@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-token-meter@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-tools@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-util-crypto@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-util-time@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-util-values@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-user-approval@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-workspace@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-system-prompt@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-timeout@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-scope@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-jobs@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-typert-protocol@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-user-questions@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-agent-preset@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-agent-preset-registry@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-api-gateway@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-api-session-controller@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-api-workspace-controller@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-store@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-ui-renderer@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-ui-session@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-deque@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-api-settings-controller@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-chunked-list@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-ui-settings-models@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-ui-workspace@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-atomic-write@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-config-editor@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-util-workspace-path@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-web-frontend@0.2.1-rc.3'\n  - '@deepseek-ai/cordis@4.0.5'\n  - '@deepseek-ai/cordis-plugin-include@1.0.10'\n  - '@deepseek-ai/cordis-plugin-loader@1.0.6'\n  - '@deepseek-ai/cosmokit@1.8.6'\n  - '@deepseek-ai/schemastery@3.18.5'\n  # The aggregate bundle mounts @mlgbnb/dsh-archive-manager at exactly 1.0.7;\n  # pnpm 11's minimum-release-age guard must not reject the fresh version.\n  # Scoped to that exact version so later upstream publishes get no cooldown bypass.\n  - '@mlgbnb/dsh-archive-manager@1.0.7'\n  - '@deepseek-ai/dsh-app-boot@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-package-manifest@0.2.1-rc.3'\n  # The satellite repositories publish the family's X.Y.Z just before this\n  # repository does, and this repository consumes each version as soon as the\n  # pin moves, so every pinned satellite version has to bypass the\n  # minimum-release-age guard. Scoped to the exact version, so a later\n  # satellite publish gets no cooldown bypass.\n  - '@linxin666/dsh-client-ui-community-plugins@0.4.13'\n  - '@linxin666/dsh-client-ui-skin-center@0.4.13'\n  - '@linxin666/dsh-pet@0.4.13'\n  - '@linxin666/dsh-client-ui-preset-center@0.4.13'\n  - '@deepseek-ai/dsh-util-code-language@0.2.1-rc.3'\n  - '@deepseek-ai/dsh-client-ui-layout@0.2.1-rc.3'\n  - '@oxlint/binding-android-arm-eabi@1.88.0'\n  - '@oxlint/binding-android-arm64@1.88.0'\n  - '@oxlint/binding-darwin-arm64@1.88.0'\n  - '@oxlint/binding-darwin-x64@1.88.0'\n  - '@oxlint/binding-freebsd-x64@1.88.0'\n  - '@oxlint/binding-linux-arm-gnueabihf@1.88.0'\n  - '@oxlint/binding-linux-arm-musleabihf@1.88.0'\n  - '@oxlint/binding-linux-arm64-gnu@1.88.0'\n  - '@oxlint/binding-linux-arm64-musl@1.88.0'\n  - '@oxlint/binding-linux-ppc64-gnu@1.88.0'\n  - '@oxlint/binding-linux-riscv64-gnu@1.88.0'\n  - '@oxlint/binding-linux-riscv64-musl@1.88.0'\n  - '@oxlint/binding-linux-s390x-gnu@1.88.0'\n  - '@oxlint/binding-linux-x64-gnu@1.88.0'\n  - '@oxlint/binding-linux-x64-musl@1.88.0'\n  - '@oxlint/binding-openharmony-arm64@1.88.0'\n  - '@oxlint/binding-win32-arm64-msvc@1.88.0'\n  - '@oxlint/binding-win32-ia32-msvc@1.88.0'\n  - '@oxlint/binding-win32-x64-msvc@1.88.0'\n  - oxlint@1.88.0\n"
